/// Generated protocol from Pigeon that represents a handler of messages from Flutter.
protocol RecorderApi {
  /// Idempotent: a second call while recording returns the running id. Must be
  /// called while the Activity is visible (the FGS is started from it, B2).
  ///
  /// `spec`: required for `intervals` and `cooper`, the fartlek spec or null
  /// for `laps`, null for `free`; anything else is `unsupportedSession`.
  /// `liveContext`: the history the live compare needs (Phase 4 §3.2; Kotlin
  /// does not read history), journaled as the `live_context` line after the
  /// header; null = no compare, no overlay, no nudges, nothing said. The
  /// previous Cooper VO2 for "up 2 on last time" is the last
  /// `cooperHistory` entry.
  /// `route`: a route to follow (Free, Trail and Goal runs), journaled as the
  /// `route` line; null = follow nothing.
  func start(mode: RecordMode, spec: SessionSpec?, units: Units, liveContext: LiveContext?, route: FollowRoute?) throws -> StartResult
  /// Debug builds only: like `start`, fed from a fixture instead of GPS/BLE.
  func startReplay(mode: RecordMode, spec: SessionSpec?, units: Units, replay: ReplayConfig) throws -> StartResult
  /// Continue an orphaned journal after the user confirms (plan §3): writes the
  /// `gap` line, rebuilds the step phase from the journal, restarts the FGS.
  /// Idempotent like `start`.
  func resumeRecovered(runId: String) throws -> StartResult
  func pause() throws
  func resume() throws
  func lap(source: LapSource) throws
  /// The "Start reps" action: ends the untimed warm-up and starts rep 1 (same
  /// effect and journal line as a first `lap(button)`); a no-op anywhere else,
  /// so a manual LAP mid-rep can never be confused with starting.
  func startReps() throws
  /// Finalises in Kotlin (journal -> tmp -> fsync -> rename -> delete journal). No-op when idle.
  func stop() throws -> String?
  func status() throws -> RecorderStatus
  /// Called on app open: journals without a finalised file, newest first. Never
  /// includes the run that is being recorded.
  func recover() throws -> [OrphanJournal]
  /// Finalise an orphaned journal without resuming it. Returns the run file
  /// path relative to the app's files dir, or null when nothing was there.
  func finalise(runId: String) throws -> String?
  /// Delete an unreadable orphan (`readable == false`). Never touches a run file.
  func discardJournal(runId: String) throws
  /// Throw the live run away (the finish screen's DISCARD): recording stops,
  /// the journal is deleted and no run file is written. False when no run is
  /// on.
  func discardRun() throws -> Bool
  func setCues(enabled: Bool) throws
  /// Pre-start location readiness (the Start screen): fixes with the
  /// recording's provider settings, a [GpsProbeEvent] about once a second.
  /// Idempotent. Stopped by [stopGpsProbe], by any start, and when the app
  /// leaves the foreground; foreground only, no service.
  func startGpsProbe() throws
  func stopGpsProbe() throws
  /// Settings → Voice → "Km splits" (default on): a Free run says each km
  /// ("3 k, 15 minutes 20, pace 5:07."). Persisted natively; applies to a run
  /// in progress too.
  func setKmSplits(enabled: Bool) throws
  /// Settings → Voice → "Spoken summary" (default on): a line as recording
  /// starts ("Trail run. Following Kastro loop, 6.2 kilometres.") and, via
  /// [speakRunSummary], one when the run is done. Persisted natively; skipped
  /// whenever voice cues are off.
  func setSpokenSummary(enabled: Bool) throws
  /// Settings → Voice → "Check-in": which metrics the km line of a Free or
  /// Trail run says besides the split, by [CheckInMetric] key in the order the
  /// runner ranks them (distance, time, pace, retrace, hrZone, heightVsStart,
  /// climb, truePace, avgPace). [zoneBottomsBpm] = the bottoms of zones 2 to 5
  /// by the runner's own HR method; null = no heart-rate line. Persisted
  /// natively; applies to a run in progress too. A run never given one (and
  /// every replay) says the plain km split.
  func setCheckIn(metrics: [String], zoneBottomsBpm: [Double]?) throws
  /// Voice coaching for the next run and any run resumed after it: persisted
  /// natively, never changes a run's journal or a replay.
  func setVoiceCoach(config: VoiceCoachConfig) throws
  /// The run's start heat slowdown (a fraction, null = none), for the live
  /// True Pace the voice coach judges: the figure the run screen's live TRUE
  /// pace uses, sent once it is fetched. Applies to the run in progress only.
  func setCoachSlowdown(slowdown: Double?) throws
  /// The end-of-run line: distance, time, average pace ([includePace] false
  /// for a 4x4 or Cooper, where a whole-run pace means nothing) and (from
  /// 20 m) the climb in [units], then [verdict] (the result screen's own words, already
  /// speakable; null when none is computed yet). Says nothing when voice cues
  /// or the spoken summary are off. Fire and forget; the audio outlives the
  /// call.
  func speakRunSummary(distanceM: Double, timeMs: Int64, climbM: Double?, verdict: String?, units: Units, includePace: Bool) throws
  /// Settings -> Run -> "Auto-pause" (default on): the recorder pauses itself
  /// when the runner stops and resumes when they move again, in Free, Laps
  /// and Goal runs (and the warm-up/cool-down of other sessions; never in a
  /// timed rep, a Cooper test or an event). Persisted natively; applies to a
  /// run in progress too.
  func setAutoPause(enabled: Bool) throws
  /// "Mute tips" in the app (LV2, A10.1): coaching off for this run only (no
  /// compare speech, no nudges; the app hides the card), the same as the
  /// notification action. A no-op when idle or already muted. Emits a
  /// [StateEvent] so the app re-reads `RecorderStatus.tipsMuted`.
  func muteTips() throws
  /// The user's volume-key LAP setting for Laps runs, persisted natively (the
  /// recorder reads it at start). Takes effect from the next run or resume,
  /// not the live one. Unset means on. Intervals, Free and Cooper never use
  /// volume keys, whatever this says. A no-op in effect where
  /// `PermissionsApi.volumeKeyLapsSupported()` is false.
  func setVolumeKeyLaps(enabled: Bool) throws
  /// The live run's simplified route from point [fromIndex] on, as flat
  /// `[lat, lon, lat, lon, ...]` (the live map's catch-up after the screen
  /// was recreated or a [RoutePointsEvent] was missed). Empty when idle.
  /// Read-only: recording never depends on it.
  func routeSince(fromIndex: Int64) throws -> [Double]
  /// The route the live run follows (as `start` got it, or as the journal had
  /// it after a restore), so the map can draw it under the runner's track.
  /// Null when idle or the run follows none. Read-only.
  func followedRoute() throws -> FollowRoute?
  /// Run files on disk (`runs/` + `runs-archive/`) as `runId -> relative path`,
  /// for the Dart Reconciler. Journals and sidecars are not listed.
  func listRunFiles() throws -> [String: String]
  /// Was the previous process killed by the OS while `runId` was recording?
  func exitDiagnosis(runId: String) throws -> ExitDiagnosis
}

